import React, { useState } from "react";
import SpiritualRoutineCard from "../components/SpiritualRoutineCard";
import SatsangCard from "../components/SatsangCard";
import RoutineTimeline from "../components/RoutineTimeline";
import MotivationCard from "../components/MotivationCard";

export default function RoutinePage() {
  const [japDone, setJapDone] = useState(false);

  const [selfCheck, setSelfCheck] = useState({
    jap: false,
    satsang: false,
    mobile: false
  });

  const [satsang, setSatsang] = useState({
    mandir: false,
    group: false,
    bhajan: false
  });

  return (
    <div style={container}>
      <h2>🧭 Spiritual Routine</h2>

      <MotivationCard />

      <SpiritualRoutineCard
        japDone={japDone}
        setJapDone={setJapDone}
        selfCheck={selfCheck}
        setSelfCheck={setSelfCheck}
      />

      <SatsangCard satsang={satsang} setSatsang={setSatsang} />

      <RoutineTimeline />
    </div>
  );
}

const container = {
  maxWidth: "500px",
  margin: "auto",
  padding: "15px"
};
